  function seedCurrentState(){
    if(app.__academySeeded)return;
    app.__academySeeded=true;
    function runSeed(){
      var data=app.state&&app.state.data||{};
      (data.items||[]).forEach(function(i){
        if(i.locWrittenBy&&(i.status==='Written'||i.status==='Done'))award('written:item:'+i.id,'written',i.code||i.id,{timestamp:number(i.lastModified)||Date.now(),silent:true,backfill:true},i.locWrittenBy);
        if(i.doneBy&&i.status==='Done')award('received:item:'+i.id,'received',i.code||i.id,{timestamp:number(i.lastModified)||Date.now(),silent:true,backfill:true},i.doneBy);
        if(i.labelPrintedBy&&i.labelPrintCount>0)award('print_label:item:'+i.id,'print_label',i.code||i.id,{timestamp:number(i.labelLastPrintedAt)||Date.now(),silent:true,backfill:true},i.labelPrintedBy);
      });
      (data.replenishmentJobs||[]).forEach(function(j){
        if(j.status==='Done'&&j.assignedTo)award('topup:job:'+j.id,'topup',j.item||j.id,{timestamp:number(j.finishTime)||number(j.lastModified)||Date.now(),silent:true,backfill:true},j.assignedTo);
        if(j.topupIssue&&j.topupIssue.status==='resolved'&&j.topupIssue.resolvedBy)award('issue:topup:'+j.id+':'+(j.topupIssue.reportedAt||'1'),'issue',j.item||j.id,{timestamp:number(j.topupIssue.resolvedAt)||number(j.lastModified)||Date.now(),silent:true,backfill:true},j.topupIssue.resolvedBy);
      });
      (data.moveJobs||[]).forEach(function(m){var u=m.confirmedBy||m.completedBy;if(m.status==='Done'&&u)award('move:job:'+m.id,'move',m.code||m.item||m.id,{timestamp:number(m.completedAt)||number(m.lastModified)||Date.now(),silent:true,backfill:true},u);});
      (data.history||[]).forEach(function(h){
        var action=clean(h.action).toLowerCase(),category='',ts=number(h.timestamp)||Date.now(),who=userName(h.user),itemText=clean(h.item);
        if(action==='write'||action==='admin-assign'||action==='admin-edit')category='written';
        else if(action==='done'||action==='received')category='received';
        else if(action==='topup')category='topup';
        else if(action==='move')category='move';
        if(!category||!who)return;
        var represented=false;
        if(ts>=seasonInfo(Date.now(),0).start){
          if(category==='written')represented=(data.items||[]).some(function(i){return clean(i.code)===itemText&&userKey(i.locWrittenBy)===userKey(who)&&(i.status==='Written'||i.status==='Done');});
          if(category==='received')represented=(data.items||[]).some(function(i){return clean(i.code)===itemText&&userKey(i.doneBy)===userKey(who)&&i.status==='Done';});
          if(category==='topup')represented=(data.replenishmentJobs||[]).some(function(j){return clean(j.item)===itemText&&userKey(j.assignedTo)===userKey(who)&&j.status==='Done';});
          if(category==='move')represented=(data.moveJobs||[]).some(function(m){return (clean(m.item)===itemText||clean(m.code)===itemText)&&userKey(m.confirmedBy||m.completedBy)===userKey(who)&&m.status==='Done';});
        }
        if(!represented)award('legacy-history:'+safeId(h.id||[action,h.item,h.timestamp].join(':')),category,h.item||h.loc||h.id,{timestamp:ts,silent:true,backfill:true,source:'history'},who);
      });
      var notes=app.state&&app.state.noteWall&&app.state.noteWall.notes||[];
      notes.forEach(function(note){(note.history||[]).forEach(function(h,idx){if(h.action==='ack'&&h.by)award('note_ack:'+note.id+':'+userKey(h.by),'note_ack',note.text||note.id,{timestamp:number(h.ts)||number(note.updatedAt)||Date.now(),silent:true,backfill:true},h.by);if(h.action==='done'&&h.by)award('note_done:'+note.id,'note_done',note.text||note.id,{timestamp:number(h.ts)||number(note.closedAt)||Date.now(),silent:true,backfill:true},h.by);});});
    }
    // Manual maintenance only: automatic backfill on every device was the
    // largest avoidable Firestore read/write consumer.
    setTimeout(runSeed,200);
  }

