  function renderIfVisible(){var v=document.getElementById('sup-view-leaderboard');if(v&&!v.classList.contains('hidden'))render();var modal=document.getElementById('academy-profile-modal');if(modal)renderMyProfileModalContent();}
  function currentSeasonOptions(){var list=[];for(var i=-7;i<=0;i++)list.push(seasonInfo(Date.now(),i));return list;}
