  function toolbarHtml(){var ranges=[['today','วันนี้'],['week','7 วัน'],['month','30 วัน'],['season','ซีซัน'],['custom','กำหนดเอง']],cats=[['overall','Overall'],['exp','EXP'],['written','Written'],['received','Receiving'],['move','Move'],['toplocation','Top Location'],['topup','Top Up'],['issue','Problem Solver'],['print','Print'],['note','Note Wall']];var custom=A.range==='custom'?'<div class="academy-range academy-custom-range"><input id="academy-custom-start" type="date" value="'+esc(A.customStart)+'" class="academy-search"><span>ถึง</span><input id="academy-custom-end" type="date" value="'+esc(A.customEnd)+'" class="academy-search"><button type="button" id="academy-apply-custom" class="is-active">ใช้ช่วงวันที่</button></div>':'';return '<div class="academy-toolbar"><div><div class="academy-range">'+ranges.map(function(x){return '<button type="button" data-academy-range="'+x[0]+'" class="'+(A.range===x[0]?'is-active':'')+'">'+x[1]+'</button>';}).join('')+'</div>'+custom+'<div class="academy-categories">'+cats.map(function(x){return '<button type="button" data-academy-category="'+x[0]+'" class="'+(A.category===x[0]?'is-active':'')+'">'+x[1]+'</button>';}).join('')+'</div></div><input id="academy-search" class="academy-search" value="'+esc(A.search)+'" placeholder="ค้นหาพนักงาน..." aria-label="ค้นหาพนักงาน"></div>';}
  function kpisHtml(sum){return '<div class="academy-kpis"><div class="academy-kpi"><span>พนักงานที่มีผลงาน</span><b>'+fmt(sum.people)+'</b><small>ในช่วงที่เลือก</small></div><div class="academy-kpi"><span>งานที่ยืนยันและนับคะแนน</span><b>'+fmt(sum.events)+'</b><small>Event ID ซ้ำไม่นับ</small></div><div class="academy-kpi"><span>ผ่านโดยไม่แก้ไข</span><b>'+number(sum.accuracy).toFixed(1)+'%</b><small>วัดจากงานที่ยืนยันแล้ว</small></div><div class="academy-kpi"><span>คำขอรอดำเนินการ</span><b>'+fmt(sum.pending)+'</b><small>รวมรอตรวจและอนุมัติแล้ว</small></div></div>';}
  function leaderboardHtml(metrics,selected,sum){var ranked=metrics.filter(function(m){return m.distinct>0;}),top=ranked.slice(0,3);return kpisHtml(sum)+(top.length?'<div class="academy-podium">'+top.map(function(m,i){return podiumCard(m,i+1);}).join('')+'</div>':'')+'<div class="academy-main-grid"><div><div class="academy-card"><div class="academy-card-head"><div><h3>อันดับพนักงาน</h3><p>'+esc(boundsForRange(A.range).label)+' · เรียงคะแนนผลงานจากมากไปน้อย · คะแนนเท่ากันดู EXP และคุณภาพงาน · ผู้ยังไม่มีผลงานจะยังไม่จัดอันดับ</p></div><span class="academy-rank-pill"><i class="ph ph-shield-check"></i> ตรวจสอบจาก Event ID</span></div><div class="academy-table-head"><div>อันดับ</div><div>พนักงาน</div><div>คะแนนผลงาน ↓</div><div>EXP</div><div>งานเด่น</div><div>ผ่านไม่แก้</div><div>แร็งค์</div></div><div class="academy-list">'+(metrics.length?metrics.map(function(m,i){return employeeRow(m.distinct?i+1:0,m,selected);}).join(''):'<div class="academy-empty"><i class="ph ph-trophy"></i><b>ยังไม่มีข้อมูลคะแนน</b><p>ทำงานในระบบแล้ว EXP และ Points จะเข้าที่นี่อัตโนมัติ</p></div>')+'</div></div>'+chartsHtml(selected)+'</div>'+characterHtml(selected)+'</div>';}
  function podiumCard(m,place){var medal=place===1?'🥇':place===2?'🥈':'🥉';return '<button type="button" class="academy-podium-card '+(place===1?'first':place===2?'second':'third')+'" data-academy-user="'+esc(m.name)+'" data-place="'+place+'"><img src="'+m.rank.rank.img+'" alt="'+esc(m.rank.rank.name)+'"><div><span class="academy-rank-pill">'+medal+' TEAM #'+place+'</span><h3>'+esc(m.name)+'</h3><p>'+esc(m.strongest)+'</p><span class="academy-rank-pill">'+esc(m.rank.rank.name)+' ('+m.rank.rank.roman+')</span><div class="academy-podium-score"><b>'+fmt(scoreFor(m))+'</b><span>'+(A.category==='overall'?'คะแนนผลงาน':'ผลงานหมวดนี้')+'</span></div></div></button>';}
  function employeeRow(place,m,selected){var trend=m.distinct===0?'รอเริ่มงาน':m.performance>=80?'+ ดี':m.performance>=65?'คงที่':'กำลังพัฒนา';return '<button type="button" class="academy-row '+(selected&&selected.key===m.key?'is-selected':'')+'" data-academy-user="'+esc(m.name)+'"><div class="academy-place">'+(place===0?'—':place<=3?['🥇','🥈','🥉'][place-1]:String(place).padStart(2,'0'))+'</div><div class="academy-person">'+(m.photo?'<img class="academy-person-avatar" src="'+m.photo+'" alt="">':'<span class="academy-person-avatar">'+esc(m.name.slice(0,2))+'</span>')+'<div><b>'+esc(m.name)+'</b><small>'+esc(m.strongest)+' · '+m.rank.rank.name+'</small></div></div><div class="academy-metric"><span>คะแนนผลงาน</span><b>'+fmt(m.performance)+'</b><small class="academy-trend '+(m.performance<65?'down':'')+'">'+trend+'</small></div><div class="academy-metric"><span>EXP ช่วงนี้</span><b>'+fmt(m.rangeExp)+'</b><small>'+fmt(m.events.length)+' เหตุการณ์</small></div><div class="academy-metric academy-hide-mobile"><span>งานเด่น</span><b>'+fmt(Math.max(m.categoryCount('written'),m.categoryCount('received'),m.categoryCount('topup'),m.categoryCount('move')))+'</b><small>'+esc(m.strongest)+'</small></div><div class="academy-metric academy-hide-mobile"><span>ผ่านโดยไม่แก้</span><b>'+m.quality+'%</b><small>'+fmt(m.cleanCount)+' งานสะอาด</small></div><img class="academy-mini-rank" src="'+m.rank.rank.img+'" alt="ตรา '+esc(m.rank.rank.name)+'"></button>';}
  function characterHtml(m){var r=m.rank,l=m.level,team=allMetrics(),place=m.distinct?team.findIndex(function(x){return x.key===m.key;})+1:0;return '<aside class="academy-card academy-character"><div class="academy-character-hero"><div class="academy-character-top"><div class="academy-character-image"><img src="'+r.rank.img+'" alt="ตราแร็งค์ '+esc(r.rank.name)+'"><span class="academy-character-level">CAREER LEVEL '+l.level+'</span></div><div class="academy-character-info"><span class="academy-tier-label">'+(place?'TEAM #'+place:'ยังไม่มีอันดับ')+' · RANK '+r.rank.roman+'</span><h3>'+esc(m.name)+'</h3><p>'+esc(m.strongest)+' · '+esc(r.rank.th)+'</p><div class="academy-profile-wallet"><div><span>Season EXP</span><b>'+fmt(m.seasonExp)+'</b><small>รีเซ็ตทุกซีซัน</small></div><div><span>Lifetime EXP</span><b>'+fmt(m.lifetimeExp)+'</b><small>สะสมตลอด</small></div><div><span>Reward Points</span><b>'+fmt(m.rewardPoints)+'</b><small>ใช้แลกรางวัล</small></div></div><div class="academy-exp-box"><div class="academy-exp-head"><span>'+r.rank.name+' ('+r.rank.roman+')</span><b>'+Math.round(r.progress)+'%</b></div><div class="academy-exp-track"><i style="width:'+r.progress+'%"></i></div><div class="academy-exp-foot"><span>'+fmt(m.seasonExp)+' EXP</span><span>'+(r.next?'อีก '+fmt(r.remaining)+' ถึง '+r.next.name:'แร็งค์สูงสุด')+'</span></div></div></div></div></div><div class="academy-character-body"><div class="academy-stat-grid"><div class="academy-stat"><span>คะแนนผลงาน</span><b>'+m.performance+'</b></div><div class="academy-stat"><span>ผ่านโดยไม่แก้ไข</span><b>'+m.quality+'%</b></div><div class="academy-stat"><span>งานหลากหลาย</span><b>'+m.distinct+'</b></div><div class="academy-stat"><span>Written</span><b>'+m.categoryCount('written')+'</b></div><div class="academy-stat"><span>Receiving</span><b>'+m.categoryCount('received')+'</b></div><div class="academy-stat"><span>Top Up</span><b>'+m.categoryCount('topup')+'</b></div></div>'+skillHtml('ผลิตภาพ',m.productivity)+skillHtml('ผ่านโดยไม่แก้',m.quality)+skillHtml('ความหลากหลาย',m.diversity)+skillHtml('ความสม่ำเสมอ',m.consistency)+'<div class="academy-insight"><b>จุดเด่น:</b> '+esc(m.strongest)+' · ทำงาน '+m.events.length+' เหตุการณ์ในช่วงนี้<br><b>คำแนะนำ:</b> '+(m.distinct<3?'ลองทำงานให้หลากหลายอย่างน้อย 3 ประเภท':'รักษาคุณภาพงานและตรวจสอบก่อนยืนยัน')+'</div><div class="academy-character-actions"><button type="button" class="primary" data-academy-open-profile><i class="ph ph-user-focus"></i> ดูโปรไฟล์และประวัติ</button><button type="button" data-academy-view="missions"><i class="ph ph-sparkle"></i> วิธีรับคะแนน</button></div></div></aside>';}
  function skillHtml(label,value){return '<div class="academy-skill"><span>'+esc(label)+'</span><div class="academy-skill-track"><i style="width:'+Math.max(0,Math.min(100,value))+'%"></i></div><b>'+fmt(value)+'</b></div>';}
  function chartsHtml(m){var groups=[['Written',m.categoryCount('written')],['Receive',m.categoryCount('received')],['Move',m.categoryCount('move')],['Top Loc',m.categoryCount('toplocation')],['Top Up',m.categoryCount('topup')],['Issue',m.categoryCount('issue')],['Print',m.categoryCount('print')]],max=Math.max.apply(null,groups.map(function(x){return x[1];}).concat([1]));var bars=groups.map(function(x){return '<div class="academy-bar-col"><div class="academy-bar" style="height:'+Math.max(4,x[1]/max*118)+'px" title="'+x[0]+' '+x[1]+'"></div><small>'+x[0]+'<br>'+x[1]+'</small></div>';}).join('');var daily={};m.events.forEach(function(e){var k=dayKey(eventTs(e));daily[k]=(daily[k]||0)+number(e.exp);});var keys=Object.keys(daily).sort().slice(-12),vals=keys.map(function(k){return daily[k];}),mx=Math.max.apply(null,vals.concat([1])),pts=vals.map(function(v,i){var x=10+(keys.length<=1?0:i*(340/(keys.length-1))),y=135-v/mx*115;return x+','+y;}).join(' ');if(!pts)pts='10,135 350,135';return '<div class="academy-charts"><div class="academy-chart"><h4>ประเภทงานของ '+esc(m.name)+'</h4><div class="academy-bar-chart">'+bars+'</div></div><div class="academy-chart"><h4>EXP ย้อนหลังรายวัน</h4><svg class="academy-line-svg" viewBox="0 0 360 150" role="img" aria-label="EXP ย้อนหลัง"><line class="grid" x1="0" y1="35" x2="360" y2="35"/><line class="grid" x1="0" y1="75" x2="360" y2="75"/><line class="grid" x1="0" y1="115" x2="360" y2="115"/><polyline class="line" points="'+pts+'"/></svg></div></div>';}
  function scoringGuideHtml(){var keys=Object.keys(TASKS).filter(function(k){return ['bonus','mission','game'].indexOf(baseGroup(k))<0;});return '<section class="academy-card academy-scoring-guide"><div class="academy-card-head"><div><span class="academy-eyebrow">VERIFIED EARNING RULES</span><h3>รับ EXP และ Reward Points จากไหน</h3><p>ระบบบันทึกคะแนนเมื่องานสำเร็จจริง พร้อม Event ID และรายการอ้างอิง ตรวจสอบย้อนหลังได้ทุกคะแนน</p></div><span class="academy-rank-pill"><i class="ph ph-shield-check"></i> งานซ้ำไม่นับ</span></div><div class="academy-rule-notice"><i class="ph ph-game-controller"></i><div><b>รางวัลจาก PLAS Quest เมื่อจบซีซัน</b><span>คะแนนเกมจะถูกแปลงเป็น Reward Points ตามระดับ เนื้อเรื่อง บอสโลก และอันดับ โดย Admin ตรวจตัวอย่างและยืนยันก่อนส่งเข้าระบบ รายการจะแสดงในประวัติคะแนนและไม่นำไปคำนวณคะแนนผลงาน WMS</span></div></div><div class="academy-rule-notice"><i class="ph ph-gauge"></i><div><b>Soft Cap รายวันเพื่อความยุติธรรม</b><span>ช่วงแรกได้ 100% · หลังเกณฑ์แรกได้ 70% · หลังเกณฑ์ที่สองได้ 40% โดยจำนวนด้านล่างคือเกณฑ์ของแต่ละงาน</span></div></div><div class="academy-score-table"><div class="academy-score-head"><span>งานที่ได้รับคะแนน</span><span>EXP</span><span>Points</span><span>100% / วัน</span><span>70% ถึง</span></div>'+keys.map(function(k){var t=TASKS[k];return '<div class="academy-score-row"><span><i>'+t.icon+'</i><b>'+esc(t.label)+'</b><small>'+esc(k)+'</small></span><strong>+'+fmt(t.exp)+'</strong><strong>+'+fmt(t.points)+'</strong><span>'+fmt(t.full)+' งาน</span><span>'+fmt(t.mid)+' งาน</span></div>';}).join('')+'</div></section>';}
  function missionsHtml(m){var dayEvents=A.events.filter(function(e){return e.userKey===m.key&&e.dayKey===dayKey();}),wk=weekKey(),weekEvents=A.events.filter(function(e){return e.userKey===m.key&&e.weekKey===wk;});var daily=MISSIONS.filter(function(x){return x.scope==='day';}),weekly=MISSIONS.filter(function(x){return x.scope==='week';});return scoringGuideHtml()+'<div class="academy-section-grid"><div class="academy-mission-card"><h3>ภารกิจรายวัน · '+esc(m.name)+'</h3><p>รีเซ็ตทุกวัน และรับโบนัสอัตโนมัติเมื่อทำครบ</p>'+daily.map(function(x){return missionRow(x,missionProgress(x,dayEvents),m);}).join('')+'</div><div class="academy-mission-card"><h3>ภารกิจรายสัปดาห์</h3><p>ส่งเสริมงานหลากหลาย ไม่เน้นปริมาณงานชนิดเดียว</p>'+weekly.map(function(x){return missionRow(x,missionProgress(x,weekEvents),m);}).join('')+'</div><div class="academy-mission-card"><h3>ความสำเร็จ</h3><p>ตราความสำเร็จจากผลงานสะสม</p>'+achievementRows(m)+'</div><div class="academy-mission-card"><h3>รายการคะแนนล่าสุด</h3><p>แสดงทั้ง EXP, Points, อัตราคูณ และ Event ID</p><div class="academy-ledger">'+ledgerRows(m.events.slice().sort(function(a,b){return eventTs(b)-eventTs(a);}).slice(0,20))+'</div></div></div>';}
  function missionRow(m,progress,metric){var task=TASKS[m.reward],done=progress>=m.target;return '<div class="academy-mission-row"><div class="academy-mission-icon">'+m.icon+'</div><div><b>'+esc(m.label)+'</b><small>'+esc(m.description)+'</small><div class="academy-mission-progress"><i style="width:'+Math.min(100,progress/m.target*100)+'%"></i></div></div><div class="academy-mission-reward"><b>+'+fmt(task.exp)+' EXP</b><strong>+'+fmt(task.points)+' Points</strong><span>'+(done?'สำเร็จแล้ว':progress+' / '+m.target)+'</span></div></div>';}
  function achievementRows(m){var all=A.events.filter(function(e){return e.userKey===m.key;}),counts=countByCategory(all),ach=[['✍️','Location Writer 100',number(counts.written)>=100],['⬆️','Top Up Specialist 50',number(counts.topup)>=50],['🛠️','Problem Solver 20',number(counts.issue)>=20],['🌈','All-Rounder','written received move topup'.split(' ').every(function(g){return all.some(function(e){return baseGroup(e.category)===g;});})],['🎓','School Guard',m.rank.rank.id>=5],['🦉','Apex Scholar',m.rank.rank.id>=6]];return ach.map(function(a){return '<div class="academy-mission-row"><div class="academy-mission-icon">'+a[0]+'</div><div><b>'+a[1]+'</b><small>'+(a[2]?'ปลดล็อกแล้ว':'ยังไม่สำเร็จ')+'</small></div><div class="academy-mission-reward"><span>'+(a[2]?'✓ UNLOCKED':'LOCKED')+'</span></div></div>';}).join('');}
  function ledgerRows(events){return events.length?events.map(function(e){var ts=eventTs(e),mult=number(e.multiplier||1),id=e.eventId||e.id||'-',isGame=baseGroup(e.category)==='game';return '<div class="academy-ledger-row academy-event-row '+(isGame?'is-game-reward':'')+'"><small>'+new Date(ts).toLocaleDateString('th-TH',{day:'2-digit',month:'short',year:'2-digit'})+'<br>'+new Date(ts).toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'})+'</small><div><b>'+esc(e.label||categoryLabel(e.category))+'</b><span class="academy-ledger-ref">อ้างอิง: '+esc(e.reference||'-')+'</span><span class="academy-event-id"><i class="ph ph-shield-check"></i> Event ID: '+esc(id)+'</span></div><div class="academy-ledger-values">'+(isGame?'<strong>🎮 รางวัลจบซีซัน</strong>':'<strong>+'+fmt(e.exp)+' EXP</strong>')+'<b>+'+fmt(e.points)+' Reward Points</b><span>'+(isGame?'ส่งจากศูนย์ควบคุมเกม':'อัตรา '+Math.round(mult*100)+'%')+'</span></div></div>';}).join(''):'<div class="academy-empty"><b>ยังไม่มีรายการคะแนน</b><p>เมื่อยืนยันงานสำเร็จ รายการจะปรากฏที่นี่</p></div>';}
  function rewardsHtml(m){var rewards=availableRewards(),mine=A.redemptions.filter(function(r){return r.userKey===m.key;});return '<div class="academy-card academy-shop"><div class="academy-card-head"><div><span class="academy-eyebrow">REWARD SHOP</span><h3>รางวัลและคำขอ</h3><p>Reward Points ไม่รีเซ็ตตามซีซัน และทุกคำขอมีสถานะตรวจสอบย้อนหลัง</p></div><div class="academy-points-balance"><img src="assets/academy/points.png" alt=""><span>ยอดคงเหลือ</span><b>'+fmt(m.rewardPoints)+' Points</b></div></div><div class="academy-reward-grid">'+rewards.map(function(r){return rewardCard(r,m);}).join('')+'</div></div><div class="academy-card"><div class="academy-card-head"><div><h3>ประวัติการแลกของ '+esc(m.name)+'</h3><p>หักแต้มเมื่อส่งคำขอ และคืนให้อัตโนมัติเมื่อ Supervisor ปฏิเสธ</p></div></div><div class="academy-ledger academy-redemption-list">'+(mine.length?mine.map(redemptionRow).join(''):'<div class="academy-empty"><i class="ph ph-gift"></i><b>ยังไม่มีประวัติการแลก</b></div>')+'</div></div>';}
  function rewardCard(r,m){var special=r.type==='strike_removal',stock=special?'ดำเนินการภายนอก':r.stock==null?'ไม่จำกัด':'คงเหลือ '+fmt(r.stock),can=m.rewardPoints>=number(r.cost)&&r.active!==false&&(special||number(r.stock)!==0);return '<article class="academy-reward-card '+(special?'is-special':'')+'"><span class="academy-reward-stock">'+stock+'</span><div class="academy-reward-icon">'+esc(r.icon||'🎁')+'</div><span class="academy-reward-type">'+(special?'คำขอพิเศษ':'ของรางวัล')+'</span><h3>'+esc(r.name)+'</h3><p>'+esc(r.description||'')+'</p><div class="academy-reward-cost"><img src="assets/academy/points.png" alt=""> '+fmt(r.cost)+' Points</div><button type="button" data-redeem="'+esc(r.id)+'" '+(can?'':'disabled')+'>'+(can?(special?'ยื่นคำขอ':'เลือกแลก'):'แต้มไม่เพียงพอ / หมด')+'</button></article>';}
  function redemptionRow(r){var special=r.type==='strike_removal'||r.rewardId==='external-strike-removal',review=r.approvedBy||r.reviewedBy||'',done=r.fulfilledBy||'';return '<div class="academy-ledger-row academy-redemption-row"><small>'+new Date(number(r.createdAt)).toLocaleDateString('th-TH',{day:'2-digit',month:'short',year:'numeric'})+'<br>'+new Date(number(r.createdAt)).toLocaleTimeString('th-TH',{hour:'2-digit',minute:'2-digit'})+'</small><div><b>'+esc(r.rewardName)+'</b><span class="academy-status '+esc(r.status)+'">'+esc(redemptionStatus(r.status))+'</span>'+(special?'<span class="academy-ledger-ref">เลขอ้างอิงภายนอก: '+esc(r.externalReference||'-')+'</span><span class="academy-ledger-ref">เหตุผล: '+esc(r.externalReason||'-')+'</span>':'')+(review?'<span class="academy-ledger-ref">ตรวจโดย '+esc(review)+'</span>':'')+(done?'<span class="academy-ledger-ref">ยืนยันเสร็จโดย '+esc(done)+'</span>':'')+(r.rejectReason?'<span class="academy-ledger-ref">เหตุผลปฏิเสธ: '+esc(r.rejectReason)+'</span>':'')+'</div><div class="academy-ledger-values"><strong>-'+fmt(r.cost)+' Points</strong>'+(r.status==='rejected'?'<b class="is-refund">คืนแต้มแล้ว</b>':'<span>'+esc(special?'ลบขีดภายนอก 1 ขีด':'คำขอแลกรางวัล')+'</span>')+'</div></div>';}
  function historyHtml(metrics){var seasons=currentSeasonOptions().slice().reverse();return '<div class="academy-card"><div class="academy-card-head"><div><h3>Season History</h3><p>ดูผลย้อนหลังทุก 3 เดือน · Lifetime EXP และ Reward Points ไม่หาย</p></div></div><div class="academy-history-list" style="padding:12px">'+seasons.map(function(s){var ev=A.events.filter(function(e){return eventTs(e)>=s.start&&eventTs(e)<=s.end;}),leader={};ev.forEach(function(e){leader[e.userKey]=(leader[e.userKey]||0)+number(e.exp);});var top=Object.keys(leader).sort(function(a,b){return leader[b]-leader[a];})[0],p=A.profiles.find(function(x){return (x.userKey||x.id)===top;}),rank=rankInfo(top?leader[top]:0).rank;return '<div class="academy-history-card"><img src="'+rank.img+'" alt=""><div><h3>'+esc(s.title)+'</h3><p>'+(ev.length?fmt(ev.length)+' events · Champion '+esc(p&&p.displayName||'-'):'ยังไม่มีข้อมูลในซีซันนี้')+'</p><span class="academy-rank-pill">'+rank.name+' ('+rank.roman+')</span></div><strong>'+fmt(top?leader[top]:0)+'<span>Champion EXP</span></strong></div>';}).join('')+'</div></div>';}
  function manageHtml(metrics){
    var requests=A.redemptions.filter(function(r){return r.status==='pending'||r.status==='approved';});
    var taskKeys=Object.keys(DEFAULT_TASKS).filter(function(k){return ['bonus','mission','game'].indexOf(baseGroup(k))<0;});
    var strike=availableRewards().find(function(r){return r.id==='external-strike-removal';})||DEFAULT_REWARDS[0];
    var requestRows=requests.length?requests.map(function(r){
      var special=r.type==='strike_removal'||r.rewardId==='external-strike-removal';
      var actions=r.status==='pending'
        ?'<button class="academy-btn primary" data-redemption-action="approved" data-id="'+r.id+'"><i class="ph ph-check"></i> อนุมัติคำขอ</button><button class="academy-btn danger" data-redemption-action="rejected" data-id="'+r.id+'">ปฏิเสธและคืนแต้ม</button>'
        :'<button class="academy-btn primary" data-redemption-action="fulfilled" data-id="'+r.id+'"><i class="ph ph-check-circle"></i> '+(special?'ยืนยันว่าลบขีดแล้ว':'ยืนยันรับของแล้ว')+'</button><button class="academy-btn danger" data-redemption-action="rejected" data-id="'+r.id+'">ยกเลิกและคืนแต้ม</button>';
      return '<div class="academy-request-card"><div class="academy-request-head"><div><span class="academy-status '+esc(r.status)+'">'+esc(redemptionStatus(r.status))+'</span><h4>'+esc(r.displayName)+' · '+esc(r.rewardName)+'</h4></div><strong>'+fmt(r.cost)+' Points</strong></div><div class="academy-request-meta"><span><i class="ph ph-calendar"></i> '+new Date(number(r.createdAt)).toLocaleString('th-TH')+'</span><span><i class="ph ph-user"></i> ผู้ส่ง '+esc(r.requestedBy||r.displayName)+'</span>'+(special?'<span><i class="ph ph-hash"></i> อ้างอิง '+esc(r.externalReference||'-')+'</span><span><i class="ph ph-note"></i> '+esc(r.externalReason||'-')+'</span>':'')+'</div><div class="academy-manage-actions">'+actions+'</div></div>';
    }).join(''):'<div class="academy-empty"><b>ไม่มีคำขอที่ต้องดำเนินการ</b></div>';
    return '<div class="academy-section-grid">'+
      '<div class="academy-manage-card academy-manage-wide"><h3>ศูนย์อนุมัติคำขอ</h3><p>ตรวจรายละเอียด อนุมัติ และยืนยันผลการดำเนินการภายนอกตามลำดับ</p><div class="academy-request-list">'+requestRows+'</div></div>'+
      '<div class="academy-manage-card academy-strike-config"><span class="academy-eyebrow">EXTERNAL WORKFLOW</span><h3>คำขอลบขีดภายนอก</h3><p>Academy เก็บเฉพาะคำขอและประวัติเท่านั้น การลบขีดจริงทำในระบบภายนอกโดย Supervisor</p><label class="academy-field"><span>ราคาแต้มต่อการลบ 1 ขีด</span><input id="academy-strike-cost" type="number" min="1" step="1000" value="'+number(strike.cost)+'"></label><div class="academy-manage-actions"><button id="academy-save-strike-cost" class="academy-btn primary"><i class="ph ph-floppy-disk"></i> บันทึกราคา</button></div><div class="academy-workflow"><span>1 ส่งคำขอ</span><i class="ph ph-arrow-right"></i><span>2 Supervisor อนุมัติ</span><i class="ph ph-arrow-right"></i><span>3 ยืนยันลบภายนอกแล้ว</span></div></div>'+
      '<div class="academy-manage-card"><h3>เพิ่มรางวัล</h3><p>ตั้งของรางวัลและราคาแต้มสำหรับเปิดแลกในอนาคต</p><div class="academy-manage-grid"><label class="academy-field"><span>ชื่อรางวัล</span><input id="academy-reward-name"></label><label class="academy-field"><span>ไอคอน Emoji</span><input id="academy-reward-icon" value="🎁"></label><label class="academy-field"><span>แต้มที่ใช้</span><input id="academy-reward-cost" type="number" min="1" value="80000"></label><label class="academy-field"><span>จำนวนคงเหลือ</span><input id="academy-reward-stock" type="number" min="0" value="10"></label></div><label class="academy-field"><span>รายละเอียด</span><textarea id="academy-reward-desc"></textarea></label><div class="academy-manage-actions"><button id="academy-save-reward" class="academy-btn primary">บันทึกรางวัล</button></div></div>'+
      '<div class="academy-manage-card"><h3>ตั้งค่าคะแนนงาน</h3><p>ปรับ EXP และ Reward Points ได้ งานซ้ำหรือ Reprint ไม่นับคะแนนเพิ่ม</p><div class="academy-ledger academy-scoring-editor">'+taskKeys.map(function(k){return '<div class="academy-ledger-row"><div><b>'+esc(TASKS[k].icon+' '+TASKS[k].label)+'</b><small>'+k+'</small></div><label class="academy-field"><span>EXP</span><input data-task-exp="'+k+'" type="number" value="'+TASKS[k].exp+'"></label><label class="academy-field"><span>Points</span><input data-task-points="'+k+'" type="number" value="'+TASKS[k].points+'"></label></div>';}).join('')+'</div><div class="academy-manage-actions"><button id="academy-save-scoring" class="academy-btn primary">บันทึกตารางคะแนน</button><button id="academy-sync-current" class="academy-btn">ซิงก์งานปัจจุบัน</button></div></div>'+
    '</div>';
  }

  function bindUI(){document.querySelectorAll('[data-academy-view]').forEach(function(b){b.addEventListener('click',function(){A.view=b.getAttribute('data-academy-view');render();});});document.querySelectorAll('[data-academy-range]').forEach(function(b){b.addEventListener('click',function(){A.range=b.getAttribute('data-academy-range');render();});});document.querySelectorAll('[data-academy-category]').forEach(function(b){b.addEventListener('click',function(){A.category=b.getAttribute('data-academy-category');render();});});document.querySelectorAll('[data-academy-user]').forEach(function(b){b.addEventListener('click',function(){A.selectedUser=b.getAttribute('data-academy-user');render();});});var search=document.getElementById('academy-search');if(search)search.addEventListener('input',function(){A.search=search.value;clearTimeout(A.searchTimer);A.searchTimer=setTimeout(render,180);});var applyCustom=document.getElementById('academy-apply-custom');if(applyCustom)applyCustom.onclick=function(){var a=document.getElementById('academy-custom-start'),b=document.getElementById('academy-custom-end');A.customStart=a&&a.value||'';A.customEnd=b&&b.value||'';if(!A.customStart||!A.customEnd||A.customStart>A.customEnd){app.showError&&app.showError('กรุณาเลือกช่วงวันที่ให้ถูกต้อง');return;}render();};var prev=document.getElementById('academy-prev-season'),next=document.getElementById('academy-next-season'),select=document.getElementById('academy-season-select');if(prev)prev.onclick=function(){A.seasonOffset=Math.max(-7,A.seasonOffset-1);render();};if(next)next.onclick=function(){A.seasonOffset=Math.min(0,A.seasonOffset+1);render();};if(select)select.onchange=function(){var all=currentSeasonOptions(),idx=all.findIndex(function(s){return s.id===select.value;});if(idx>=0)A.seasonOffset=idx-(all.length-1);render();};var guide=document.getElementById('academy-open-guide');if(guide)guide.onclick=openGuide;document.querySelectorAll('[data-academy-open-profile]').forEach(function(profile){profile.onclick=function(){openProfile(A.selectedUser);};});document.querySelectorAll('[data-redeem]').forEach(function(b){b.addEventListener('click',function(){redeemReward(b.getAttribute('data-redeem'),A.selectedUser);});});document.querySelectorAll('[data-redemption-action]').forEach(function(b){b.addEventListener('click',function(){updateRedemption(b.getAttribute('data-id'),b.getAttribute('data-redemption-action'));});});var sr=document.getElementById('academy-save-reward');if(sr)sr.onclick=saveRewardFromForm;var sc=document.getElementById('academy-save-strike-cost');if(sc)sc.onclick=saveStrikeCost;var ss=document.getElementById('academy-save-scoring');if(ss)ss.onclick=saveScoring;var sync=document.getElementById('academy-sync-current');if(sync)sync.onclick=function(){if(!confirm('ซิงก์งานเดิมเข้า Academy ตอนนี้? ระบบจะตรวจงานปัจจุบันหนึ่งรอบและอาจใช้โควตา Firestore เพิ่ม'))return;app.__academySeeded=false;seedCurrentState();app.showSuccess&&app.showSuccess('เริ่มซิงก์งานปัจจุบันหนึ่งรอบแล้ว');};}
  function openGuide(){var old=document.getElementById('academy-guide-modal');if(old)old.remove();var cards=RANKS.map(function(r,i){var next=RANKS[i+1];return '<article class="academy-guide-rank"><img src="'+r.img+'" alt="ตรา '+esc(r.name)+'"><span>RANK '+r.roman+'</span><h3>'+esc(r.name)+'</h3><p>'+esc(r.th)+'</p><b>'+fmt(r.min)+' EXP'+(next?' – '+fmt(next.min-1):' ขึ้นไป')+'</b></article>';}).join('');document.body.insertAdjacentHTML('beforeend','<div id="academy-guide-modal" class="academy-modal"><div class="academy-modal-card academy-rank-guide-dialog"><button class="academy-modal-close" id="academy-guide-close" aria-label="ปิด"><i class="ph ph-x"></i></button><div class="academy-profile-modal-inner"><span class="academy-eyebrow">SEASON RANKS</span><h2>ตราแร็งค์ PLAS Academy League</h2><p>Season EXP รีเซ็ตทุก 3 เดือน ส่วน Career Level และ Lifetime EXP สะสมต่อเนื่อง</p><div class="academy-rank-guide-grid">'+cards+'</div></div></div></div>');document.getElementById('academy-guide-close').onclick=function(){document.getElementById('academy-guide-modal').remove();};}
  function openProfile(name){ensureLoaded();A.selectedUser=userName(name||currentUser());A.profileTab='summary';var old=document.getElementById('academy-profile-modal');if(old)old.remove();document.body.insertAdjacentHTML('beforeend','<div id="academy-profile-modal" class="academy-modal"><div class="academy-modal-card academy-profile-dialog"><button class="academy-modal-close" id="academy-profile-close" aria-label="ปิด"><i class="ph ph-x"></i></button><div id="academy-profile-modal-content" class="academy-profile-modal-inner"></div></div></div>');document.getElementById('academy-profile-close').onclick=function(){document.getElementById('academy-profile-modal').remove();};renderMyProfileModalContent();}
  function profileTabHtml(tab,label,icon){return '<button type="button" data-profile-tab="'+tab+'" class="'+(A.profileTab===tab?'is-active':'')+'"><i class="ph ph-'+icon+'"></i> '+label+'</button>';}
  function renderMyProfileModalContent(){var box=document.getElementById('academy-profile-modal-content');if(!box)return;var m=metricsFor(A.selectedUser||currentUser()),events=A.events.filter(function(e){return e.userKey===m.key;}).sort(function(a,b){return eventTs(b)-eventTs(a);}).slice(0,100),redemptions=A.redemptions.filter(function(r){return r.userKey===m.key;});var panel=A.profileTab==='earnings'?'<div class="academy-card academy-profile-panel"><div class="academy-card-head"><div><h3>รายละเอียดการได้รับคะแนน</h3><p>แสดงแหล่งที่มา EXP, Reward Points, Soft Cap และ Event ID</p></div></div><div class="academy-ledger academy-profile-ledger">'+ledgerRows(events)+'</div></div>':A.profileTab==='redemptions'?'<div class="academy-card academy-profile-panel"><div class="academy-card-head"><div><h3>ประวัติการแลกและคำขอ</h3><p>ตรวจสถานะ ผู้อนุมัติ การคืนแต้ม และเลขอ้างอิงภายนอก</p></div></div><div class="academy-ledger academy-profile-ledger">'+(redemptions.length?redemptions.map(redemptionRow).join(''):'<div class="academy-empty"><b>ยังไม่มีประวัติการแลก</b></div>')+'</div></div>':'<div class="academy-card academy-profile-panel"><div class="academy-card-head"><div><h3>ภาพรวมการเติบโต</h3><p>Season Rank รีเซ็ตทุก 3 เดือน · Career Level และ Lifetime EXP สะสมตลอด</p></div></div>'+chartsHtml(m)+'<div class="academy-profile-explainer"><div><b>Season Rank</b><span>วัดจาก EXP ในซีซันปัจจุบัน ใช้แข่งขันอันดับทีม</span></div><div><b>Career Level</b><span>วัดจาก Lifetime EXP และไม่ถูกรีเซ็ต</span></div><div><b>Reward Points</b><span>สะสมเพื่อแลกรางวัลหรือยื่นคำขอลบขีดภายนอก</span></div></div></div>';box.innerHTML='<div class="academy-profile-title"><div><span class="academy-eyebrow">VERIFIED ACADEMY PROFILE</span><h2>โปรไฟล์ Academy · '+esc(m.name)+'</h2></div><span class="academy-rank-pill"><i class="ph ph-shield-check"></i> ตรวจสอบย้อนหลังได้</span></div><div class="academy-profile-tabs">'+profileTabHtml('summary','ภาพรวม','chart-line-up')+profileTabHtml('earnings','คะแนนที่ได้รับ','coins')+profileTabHtml('redemptions','การแลกและคำขอ','receipt')+'</div><div class="academy-profile-modal-grid">'+characterHtml(m).replace(/<div class="academy-character-actions">[\s\S]*?<\/div><\/div><\/aside>$/,'</div></aside>')+'<div>'+panel+'<div class="academy-character-actions academy-profile-actions"><button type="button" id="academy-open-settings"><i class="ph ph-gear"></i> ตั้งค่ารูปและ PIN</button><button type="button" class="primary" id="academy-go-rewards"><i class="ph ph-gift"></i> ไปหน้ารางวัลและคำขอ</button></div></div></div>';document.querySelectorAll('[data-profile-tab]').forEach(function(b){b.onclick=function(){A.profileTab=b.getAttribute('data-profile-tab');renderMyProfileModalContent();};});var settings=document.getElementById('academy-open-settings');if(settings)settings.onclick=function(){document.getElementById('academy-profile-modal').remove();app.openProfileSettings&&app.openProfileSettings(m.name);};var rewards=document.getElementById('academy-go-rewards');if(rewards)rewards.onclick=function(){document.getElementById('academy-profile-modal').remove();A.view='rewards';A.selectedUser=m.name;if(document.getElementById('screen-supervisor')&&!document.getElementById('screen-supervisor').classList.contains('hidden')){app.switchSupTab('leaderboard');render();}else openRewardModal(m);};}
  function openRewardModal(m){var old=document.getElementById('academy-reward-modal');if(old)old.remove();document.body.insertAdjacentHTML('beforeend','<div id="academy-reward-modal" class="academy-modal"><div class="academy-modal-card"><button class="academy-modal-close" onclick="document.getElementById(\'academy-reward-modal\').remove()"><i class="ph ph-x"></i></button><div class="academy-profile-modal-inner">'+rewardsHtml(m)+'</div></div></div>');document.querySelectorAll('#academy-reward-modal [data-redeem]').forEach(function(b){b.onclick=function(){redeemReward(b.getAttribute('data-redeem'),m.name);};});}
  function openStrikeRequest(reward,name){var old=document.getElementById('academy-strike-request-modal');if(old)old.remove();document.body.insertAdjacentHTML('beforeend','<div id="academy-strike-request-modal" class="academy-modal"><div class="academy-modal-card academy-request-dialog"><button class="academy-modal-close" id="academy-strike-close" aria-label="ปิด"><i class="ph ph-x"></i></button><div class="academy-request-icon">🛡️</div><span class="academy-eyebrow">EXTERNAL STRIKE REQUEST</span><h2>ขอลบขีดภายนอก 1 ขีด</h2><p>ใช้ '+fmt(reward.cost)+' Reward Points เมื่อส่งคำขอ จากนั้น Supervisor จะตรวจสอบและยืนยันหลังดำเนินการในระบบภายนอก</p><div class="academy-workflow"><span>1 ส่งคำขอ</span><i class="ph ph-arrow-right"></i><span>2 อนุมัติ</span><i class="ph ph-arrow-right"></i><span>3 ลบภายนอกเสร็จ</span></div><label class="academy-field"><span>เลขอ้างอิงขีดภายนอก / งานที่เกี่ยวข้อง</span><input id="academy-strike-reference" placeholder="เช่น EXT-2026-001 หรือเลขงาน" autocomplete="off"></label><label class="academy-field"><span>รายละเอียดและเหตุผลที่ขอ</span><textarea id="academy-strike-reason" placeholder="อธิบายขีดที่ต้องการขอให้ตรวจสอบ"></textarea></label><div class="academy-request-note"><i class="ph ph-info"></i> หากคำขอถูกปฏิเสธ ระบบจะคืน '+fmt(reward.cost)+' Points ให้อัตโนมัติ</div><div class="academy-character-actions"><button type="button" id="academy-strike-cancel">ยกเลิก</button><button type="button" class="primary" id="academy-strike-submit">ยืนยันส่งคำขอ</button></div></div></div>');var close=function(){var modal=document.getElementById('academy-strike-request-modal');if(modal)modal.remove();};document.getElementById('academy-strike-close').onclick=close;document.getElementById('academy-strike-cancel').onclick=close;document.getElementById('academy-strike-submit').onclick=function(){var reference=clean(document.getElementById('academy-strike-reference').value),reason=clean(document.getElementById('academy-strike-reason').value);if(!reference||!reason){app.showError&&app.showError('กรุณาระบุเลขอ้างอิงและเหตุผลให้ครบ');return;}commitRedemption(reward,name,{type:'strike_removal',externalReference:reference,externalReason:reason}).then(function(ok){if(ok)close();});};}
  function redeemReward(id,name){var reward=availableRewards().find(function(r){return r.id===id;}),p=profileFor(name);if(!reward)return;if(number(p.rewardPoints)<number(reward.cost)){app.showError&&app.showError('Reward Points ไม่เพียงพอ');return;}if(reward.type==='strike_removal'){openStrikeRequest(reward,name);return;}if(!confirm('ยืนยันเลือกแลก “'+reward.name+'” ใช้ '+fmt(reward.cost)+' Points?'))return;commitRedemption(reward,name,{type:'reward'});}
  function commitRedemption(reward,name,extra){var redRef=db.collection(COL.REDEMPTIONS).doc(),pRef=db.collection(COL.PROFILES).doc(userKey(name)),rRef=db.collection(COL.REWARDS).doc(reward.id);return db.runTransaction(function(tx){return Promise.all([tx.get(pRef),tx.get(rRef)]).then(function(sn){var prof=sn[0].exists?sn[0].data():{},rw=sn[1].exists?sn[1].data():reward;if(number(prof.rewardPoints)<number(reward.cost))throw new Error('Reward Points ไม่เพียงพอ');if(rw.stock!=null&&number(rw.stock)<=0)throw new Error('ของรางวัลหมด');tx.set(pRef,{rewardPoints:number(prof.rewardPoints)-number(reward.cost),updatedAt:Date.now()},{merge:true});if(rw.stock!=null)tx.set(rRef,{stock:number(rw.stock)-1,updatedAt:Date.now()},{merge:true});tx.set(redRef,Object.assign({id:redRef.id,userKey:userKey(name),displayName:userName(name),rewardId:reward.id,rewardName:reward.name,cost:number(reward.cost),status:'pending',createdAt:Date.now(),requestedBy:currentUser(),version:VERSION},extra||{}));});}).then(function(){app.showSuccess&&app.showSuccess(extra&&extra.type==='strike_removal'?'ส่งคำขอลบขีดภายนอกแล้ว':'ส่งคำขอแลกรางวัลแล้ว');return true;}).catch(function(e){app.showError&&app.showError(e.message||'ส่งคำขอไม่สำเร็จ');return false;});}
  function updateRedemption(id,status){
    var r=A.redemptions.find(function(x){return x.id===id;});
    if(!r)return;
    var ref=db.collection(COL.REDEMPTIONS).doc(id);
    if(status==='rejected'){
      var rejectReason=clean(prompt('ระบุเหตุผลที่ปฏิเสธและคืนแต้ม:')||'');
      if(!rejectReason)return;
      var pRef=db.collection(COL.PROFILES).doc(r.userKey),rewardRef=db.collection(COL.REWARDS).doc(r.rewardId);
      db.runTransaction(function(tx){return Promise.all([tx.get(ref),tx.get(pRef),tx.get(rewardRef)]).then(function(sn){
        var rd=sn[0].data()||{},p=sn[1].exists?sn[1].data():{},rw=sn[2].exists?sn[2].data():{};
        if(rd.status==='rejected'||rd.status==='fulfilled')return;
        tx.set(pRef,{rewardPoints:number(p.rewardPoints)+number(rd.cost),updatedAt:Date.now()},{merge:true});
        if(rw.stock!=null)tx.set(rewardRef,{stock:number(rw.stock)+1,updatedAt:Date.now()},{merge:true});
        tx.set(ref,{status:'rejected',reviewedBy:currentUser(),reviewedAt:Date.now(),rejectedBy:currentUser(),rejectedAt:Date.now(),rejectReason:rejectReason,refundAt:Date.now()},{merge:true});
      });}).then(function(){app.showSuccess&&app.showSuccess('ปฏิเสธคำขอและคืน Points แล้ว');});
    }else{
      var payload=status==='approved'?{status:'approved',reviewedBy:currentUser(),reviewedAt:Date.now(),approvedBy:currentUser(),approvedAt:Date.now()}:{status:'fulfilled',fulfilledBy:currentUser(),fulfilledAt:Date.now()};
      ref.set(payload,{merge:true}).then(function(){var special=r.type==='strike_removal'||r.rewardId==='external-strike-removal';app.showSuccess&&app.showSuccess(status==='fulfilled'?(special?'ยืนยันว่าลบขีดภายนอกแล้ว':'ยืนยันรับรางวัลแล้ว'):'อนุมัติคำขอแล้ว');});
    }
  }
  function saveRewardFromForm(){var name=clean(document.getElementById('academy-reward-name').value),icon=clean(document.getElementById('academy-reward-icon').value)||'🎁',cost=number(document.getElementById('academy-reward-cost').value),stock=number(document.getElementById('academy-reward-stock').value),desc=clean(document.getElementById('academy-reward-desc').value);if(!name||cost<=0){app.showError&&app.showError('กรุณาใส่ชื่อและแต้มรางวัล');return;}var id=safeId(name.toLowerCase())+'-'+Date.now().toString(36);db.collection(COL.REWARDS).doc(id).set({id:id,name:name,icon:icon,cost:cost,stock:stock,description:desc,active:true,createdAt:Date.now(),createdBy:currentUser()}).then(function(){app.showSuccess&&app.showSuccess('เพิ่มรางวัลแล้ว');});}
  function saveStrikeCost(){var input=document.getElementById('academy-strike-cost'),cost=Math.max(1,number(input&&input.value));if(!cost){app.showError&&app.showError('กรุณาระบุราคาแต้มที่ถูกต้อง');return;}var base=DEFAULT_REWARDS.find(function(r){return r.id==='external-strike-removal';});db.collection(COL.REWARDS).doc(base.id).set(Object.assign({},base,{cost:cost,updatedAt:Date.now(),updatedBy:currentUser()}),{merge:true}).then(function(){app.showSuccess&&app.showSuccess('บันทึกราคาคำขอลบขีดแล้ว');});}
  function saveScoring(){var tasks={};document.querySelectorAll('[data-task-exp]').forEach(function(el){var k=el.getAttribute('data-task-exp');tasks[k]=tasks[k]||{};tasks[k].exp=Math.max(0,number(el.value));});document.querySelectorAll('[data-task-points]').forEach(function(el){var k=el.getAttribute('data-task-points');tasks[k]=tasks[k]||{};tasks[k].points=Math.max(0,number(el.value));});db.collection(COL.CONFIG).doc('scoring').set({tasks:tasks,updatedAt:Date.now(),updatedBy:currentUser()},{merge:true}).then(function(){Object.keys(tasks).forEach(function(k){TASKS[k]=Object.assign({},TASKS[k],tasks[k]);});app.showSuccess&&app.showSuccess('บันทึกตารางคะแนนแล้ว');});}

